with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MLAC_EMI_PC_BANK_BRANCH_ADD as BRANCH_ADDRESS
        , cast(null as varchar) as BANK_REFERENCE_NUMBER
        , cast(null as varchar) as BRANCH_CONTACT_NUMBER
        , cast(null as varchar) as BRANCH_CONTACT_MANDATE_INDICATOR
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__BAGIC_E_CODE))) as HUB_PARTY_HK
        , cast(null as varchar) as BRANCH_ADDRESS
        , BANK_REFERENCE_NO_2 as BANK_REFERENCE_NUMBER
        , cast(null as varchar) as BRANCH_CONTACT_NUMBER
        , cast(null as varchar) as BRANCH_CONTACT_MANDATE_INDICATOR
        , 'BJAZ_GPG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_gpg_pol_dtls') }}
    where (nullif(trim(BAGIC_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CUSTOMER_ID))) as HUB_PARTY_HK
        , BRANCH_ADDRESS as BRANCH_ADDRESS
        , cast(null as varchar) as BANK_REFERENCE_NUMBER
        , BRANCH_CONTACT_NO as BRANCH_CONTACT_NUMBER
        , BRANCH_CONTACT_NO_MANDATE as BRANCH_CONTACT_MANDATE_INDICATOR
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(CUSTOMER_ID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BRANCH_ADDRESS end) as BRANCH_ADDRESS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BANK_REFERENCE_NUMBER end) as BANK_REFERENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BRANCH_CONTACT_NUMBER end) as BRANCH_CONTACT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BRANCH_CONTACT_MANDATE_INDICATOR end) as BRANCH_CONTACT_MANDATE_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when BRANCH_ADDRESS is not null or BANK_REFERENCE_NUMBER is not null or BRANCH_CONTACT_NUMBER is not null or BRANCH_CONTACT_MANDATE_INDICATOR is not null
                     then md5(upper(coalesce(cast(BRANCH_ADDRESS as varchar), '') || '|' || coalesce(cast(BANK_REFERENCE_NUMBER as varchar), '') || '|' || coalesce(cast(BRANCH_CONTACT_NUMBER as varchar), '') || '|' || coalesce(cast(BRANCH_CONTACT_MANDATE_INDICATOR as varchar), '')))
                end as SAT_PARTY_BANKING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_BANKING_HASHDIFF is not null
